CREATE TABLE document_control.interested_party_requirements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id),
  record_number integer GENERATED ALWAYS AS IDENTITY UNIQUE,
  party_group text NOT NULL CHECK (length(trim(party_group)) BETWEEN 1 AND 4000),
  party_type text NOT NULL DEFAULT 'Not assessed' CHECK (party_type IN ('Not assessed','Internal','External')),
  scope text NOT NULL DEFAULT '', requirement text NOT NULL CHECK (length(trim(requirement)) BETWEEN 1 AND 4000),
  basis text NOT NULL DEFAULT 'Not assessed' CHECK (basis IN ('Not assessed','Need / expectation','Customer requirement','Contractual requirement','Legal / regulatory requirement','Other')),
  source_reference text NOT NULL DEFAULT '', relevance text NOT NULL DEFAULT 'Not assessed' CHECK (relevance IN ('Not assessed','Relevant','Not relevant')),
  relevance_reason text NOT NULL DEFAULT '', department text NOT NULL DEFAULT '', owner_user_id uuid REFERENCES identity.users(id),
  acceptance_criteria text NOT NULL DEFAULT '', monitoring_method text NOT NULL DEFAULT '', frequency text NOT NULL DEFAULT '',
  next_review_on date, identified_on date, climate_notes text NOT NULL DEFAULT '', related_reference text NOT NULL DEFAULT '',
  lifecycle text NOT NULL DEFAULT 'Draft' CHECK (lifecycle IN ('Draft','Active','Inactive')), inactive_reason text NOT NULL DEFAULT '',
  plan_revision integer NOT NULL DEFAULT 1, version integer NOT NULL DEFAULT 1, last_verified_review_id uuid,
  source_key text, source_payload jsonb, created_by_user_id uuid REFERENCES identity.users(id),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id,id), UNIQUE (organization_id,source_key),
  CHECK (relevance='Not assessed' OR length(trim(relevance_reason))>0),
  CHECK (lifecycle<>'Inactive' OR length(trim(inactive_reason))>0),
  CHECK (lifecycle<>'Active' OR (relevance='Relevant' AND party_type<>'Not assessed' AND basis<>'Not assessed'
    AND owner_user_id IS NOT NULL AND length(trim(department))>0 AND length(trim(acceptance_criteria))>0
    AND length(trim(monitoring_method))>0 AND length(trim(frequency))>0 AND next_review_on IS NOT NULL))
);
CREATE INDEX interested_party_register ON document_control.interested_party_requirements (organization_id,record_number DESC);
CREATE INDEX interested_party_owner ON document_control.interested_party_requirements (organization_id,owner_user_id);
CREATE TABLE document_control.interested_party_monitoring (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id), requirement_id uuid NOT NULL,
  plan_revision integer NOT NULL, plan_snapshot jsonb NOT NULL CHECK (jsonb_typeof(plan_snapshot)='object'), observed_on date NOT NULL,
  observations text NOT NULL CHECK (length(trim(observations)) BETWEEN 1 AND 4000), evidence text NOT NULL CHECK (length(trim(evidence)) BETWEEN 1 AND 4000),
  outcome text NOT NULL CHECK (outcome IN ('Met','Partly met','Not met')), follow_up text NOT NULL DEFAULT '', follow_up_due_on date,
  related_reference text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Submitted' CHECK (status IN ('Submitted','Verified','Returned')),
  recorded_by_user_id uuid NOT NULL REFERENCES identity.users(id), recorded_at timestamptz NOT NULL DEFAULT now(),
  decided_by_user_id uuid REFERENCES identity.users(id), decided_at timestamptz, decision_notes text NOT NULL DEFAULT '', next_review_on date,
  UNIQUE (organization_id,requirement_id,id),
  FOREIGN KEY (organization_id,requirement_id) REFERENCES document_control.interested_party_requirements (organization_id,id),
  CHECK (outcome='Met' OR (length(trim(follow_up))>0 AND follow_up_due_on IS NOT NULL)),
  CHECK (follow_up_due_on IS NULL OR follow_up_due_on>=observed_on),
  CHECK (status='Submitted' OR (decided_at IS NOT NULL AND decided_by_user_id IS NOT NULL AND length(trim(decision_notes))>0)),
  CHECK (status<>'Verified' OR (next_review_on IS NOT NULL AND next_review_on>observed_on))
);
CREATE UNIQUE INDEX interested_party_pending ON document_control.interested_party_monitoring (requirement_id) WHERE status='Submitted';
CREATE INDEX interested_party_monitoring_history ON document_control.interested_party_monitoring (organization_id,requirement_id,recorded_at DESC);
ALTER TABLE document_control.interested_party_requirements ADD FOREIGN KEY (organization_id,id,last_verified_review_id)
  REFERENCES document_control.interested_party_monitoring (organization_id,requirement_id,id);
GRANT SELECT,INSERT,UPDATE ON document_control.interested_party_requirements,document_control.interested_party_monitoring TO mrmpl_web;
GRANT USAGE,SELECT ON SEQUENCE document_control.interested_party_requirements_record_number_seq TO mrmpl_web;
GRANT SELECT ON document_control.interested_party_requirements,document_control.interested_party_monitoring TO mrmpl_reporting;
INSERT INTO identity.permissions (key,module,name,description) VALUES
  ('iso.interested_parties.read','iso-document','View assigned interested-party requirements','View and record monitoring for requirements assigned to you.'),
  ('iso.interested_parties.read_all','iso-document','View all interested-party requirements','View every requirement, monitoring plan, result and history.'),
  ('iso.interested_parties.manage','iso-document','QA manage interested-party requirements','Assess relevance, prepare monitoring plans and assign responsible staff.'),
  ('iso.interested_parties.verify','iso-document','QA verify interested-party monitoring','Verify evidence/results or return monitoring with a reason.');
INSERT INTO identity.role_permissions (role_id,permission_id)
SELECT role.id,permission.id FROM identity.roles role CROSS JOIN identity.permissions permission
WHERE permission.key='iso.interested_parties.read'
  OR (role.key IN ('administrator','quality-assurance-hod') AND permission.key LIKE 'iso.interested_parties.%')
  OR (role.key='department-manager' AND permission.key='iso.interested_parties.read_all') ON CONFLICT DO NOTHING;
